// A small, entirely invented knowledge base for a fictional company. It is
// deliberately written so that some questions ARE answerable and some are NOT,
// which is what makes the no-answer path testable rather than decorative.
const DOCS = [
  {
    doc_id: 'POL-001', title: 'Returns and refunds policy', category: 'policy',
    audience: 'public', effective_from: '2026-01-01',
    text: 'Northwind Outdoors accepts returns within 45 days of delivery for a full refund, provided the item is unworn and in its original packaging. Sale items marked "final sale" cannot be returned. Refunds are issued to the original payment method within 10 business days of the returned item being received at the Adelaide warehouse. Return shipping is paid by the customer unless the item arrived faulty or was sent in error, in which case Northwind Outdoors covers it and sends a prepaid label.'
  },
  {
    doc_id: 'POL-002', title: 'Warranty terms', category: 'policy',
    audience: 'public', effective_from: '2026-01-01',
    text: 'All Northwind Outdoors footwear carries a 24 month warranty against manufacturing defects, measured from the date of purchase. The warranty covers delamination, stitching failure and sole separation. It does not cover normal wear of outsoles, damage from improper care, or products bought from unauthorised resellers. Warranty claims require proof of purchase and photographs of the defect.'
  },
  {
    doc_id: 'POL-003', title: 'Delivery timeframes', category: 'policy',
    audience: 'public', effective_from: '2026-03-15',
    text: 'Standard delivery within metropolitan Australia takes 3 to 5 business days. Regional and remote deliveries take 5 to 10 business days. Express delivery, where available, is next business day for orders placed before 1pm ACST on a weekday. Northwind Outdoors does not currently ship outside Australia and New Zealand.'
  },
  {
    doc_id: 'ENG-101', title: 'Waterproofing membrane technology', category: 'product',
    audience: 'public', effective_from: '2025-11-01',
    text: 'The HydroSeal membrane used in Northwind hiking boots is a microporous laminate rated to 20,000 mm hydrostatic head with a moisture vapour transmission rate of 15,000 g per square metre per 24 hours. The membrane is bonded to the boot lining rather than the outer, which keeps the seam count low. HydroSeal performance degrades if the boot is machine washed or dried above 40 degrees Celsius.'
  },
  {
    doc_id: 'ENG-102', title: 'Outsole compound selection', category: 'product',
    audience: 'public', effective_from: '2025-11-01',
    text: 'Trail models use a 62 Shore A rubber compound optimised for wet rock grip, while approach models use a firmer 70 Shore A compound that lasts longer on abrasive surfaces but is less sticky when wet. Lug depth is 5 mm on trail models and 3.5 mm on approach models.'
  },
  {
    doc_id: 'OPS-210', title: 'Warehouse cut-off times', category: 'operations',
    audience: 'internal', effective_from: '2026-02-01',
    text: 'The Adelaide warehouse despatch cut-off is 2pm ACST Monday to Friday. Orders received after cut-off are picked the following business day. The warehouse does not operate on South Australian public holidays. Peak season from 20 November to 24 December extends the cut-off to 4pm ACST with additional casual staff.'
  },
  {
    doc_id: 'OPS-211', title: 'Stock replenishment rules', category: 'operations',
    audience: 'internal', effective_from: '2026-02-01',
    text: 'Replenishment orders are raised automatically when available stock for a size and colour combination falls below 12 units. Lead time from the primary supplier is 45 days by sea and 9 days by air. Air freight is only authorised when projected stock-out is within 14 days and the affected line has sold more than 200 units in the preceding quarter.'
  },
  {
    doc_id: 'SUP-330', title: 'Sizing guidance', category: 'support',
    audience: 'public', effective_from: '2026-01-10',
    text: 'Northwind footwear is generally true to size in EU sizing. Customers between sizes should size up for trail models, which are cut narrower through the midfoot. Approach models run approximately half a size large. A printable measuring guide is available and should be used on a hard floor at the end of the day, when feet are at their largest.'
  }
];

return DOCS.map(function (d) { return { json: d }; });

const docs = $('Load Demo Corpus').all().map(function (i) { return i.json; });
const chars = docs.reduce(function (a, d) { return a + String(d.text || '').length; }, 0);
return [{ json: {
  status: 'ingested',
  collection: 'agentic_rag_demo',
  documents: docs.length,
  total_characters: chars,
  chunk_size: 700,
  chunk_overlap: 120,
  metadata_fields: ['doc_id', 'title', 'category', 'audience', 'effective_from'],
  categories: docs.map(function (d) { return d.category; }).filter(function (v, i, a) { return a.indexOf(v) === i; }),
  note: 'The demo uses the in-memory Simple Vector Store so it runs with no vector database credentials. Swap Store Chunks and Retrieve Chunks for the Qdrant nodes to use a persistent store; see the README.',
  ingested_at: new Date().toISOString()
} }];

// Metadata filtering, a deterministic hybrid rerank, and retrieval diagnostics.
// The rerank blends the vector score with lexical overlap, which reliably rescues
// exact-term matches (part numbers, policy names) that pure embeddings rank low,
// and it costs nothing and adds no latency because no model is involved.
const q = $('Normalise Query').first().json;
const raw = $input.all().map(function (i) { return i.json; });

function unpack(r, idx) {
  const doc = r.document || r;
  const meta = doc.metadata || r.metadata || {};
  return {
    rank: idx,
    text: String(doc.pageContent || doc.text || r.text || ''),
    score: typeof r.score === 'number' ? r.score : (typeof doc.score === 'number' ? doc.score : null),
    doc_id: meta.doc_id || null,
    title: meta.title || null,
    category: meta.category || null,
    audience: meta.audience || null,
    effective_from: meta.effective_from || null
  };
}

const all = raw.map(unpack).filter(function (c) { return c.text.length > 0; });

// ---- Metadata filtering -------------------------------------------------
// Audience is genuine access control here: an internal document must not be
// quoted back to a public caller even when it is the best semantic match.
const filteredOut = [];
const visible = all.filter(function (c) {
  if (q.audience === 'public' && c.audience && c.audience !== 'public') {
    filteredOut.push({ doc_id: c.doc_id, reason: 'audience "' + c.audience + '" is not visible to a public caller' });
    return false;
  }
  if (q.category_filter && c.category && c.category !== q.category_filter) {
    filteredOut.push({ doc_id: c.doc_id, reason: 'category "' + c.category + '" excluded by filter "' + q.category_filter + '"' });
    return false;
  }
  return true;
});

// ---- Lexical overlap ----------------------------------------------------
const STOP = { the: 1, a: 1, an: 1, of: 1, to: 1, in: 1, on: 1, for: 1, and: 1, or: 1, is: 1, are: 1, do: 1, does: 1, i: 1, my: 1, how: 1, what: 1, when: 1, can: 1, long: 1, have: 1, you: 1, your: 1, it: 1, be: 1, there: 1, that: 1, this: 1 };
const qTerms = String(q.question).toLowerCase().replace(/[^a-z0-9\s]/g, ' ').split(/\s+/)
  .filter(function (w) { return w.length > 2 && !STOP[w]; });

function lexical(text) {
  if (!qTerms.length) { return 0; }
  const lower = text.toLowerCase();
  let hits = 0;
  qTerms.forEach(function (t) { if (lower.indexOf(t) !== -1) { hits++; } });
  return hits / qTerms.length;
}

// Not every vector store returns a numeric similarity score. When none is
// available, fall back to RANK POSITION, which the store has already sorted by
// similarity. Without this the relevance gate would silently become
// lexical-only and would drop good semantic matches that share no exact terms.
const scores = visible.map(function (c) { return c.score; }).filter(function (s) { return typeof s === 'number'; });
const haveScores = scores.length > 0;
const maxScore = haveScores ? Math.max.apply(null, scores) : 1;
const minScore = haveScores ? Math.min.apply(null, scores) : 0;
const rankBasis = Math.max(1, all.length);

function normScore(c) {
  if (!haveScores || typeof c.score !== 'number') {
    return Math.max(0.2, 1 - (c.rank / rankBasis));
  }
  if (maxScore - minScore < 1e-9) { return 1; }
  return (c.score - minScore) / (maxScore - minScore);
}

const W_VEC = 0.7;
const W_LEX = 0.3;
const ranked = visible.map(function (c) {
  const lex = lexical(c.text);
  return Object.assign({}, c, {
    lexical_overlap: Math.round(lex * 1000) / 1000,
    vector_score: c.score,
    score_basis: haveScores ? 'vector_similarity' : 'rank_position_fallback',
    rerank_score: Math.round((W_VEC * normScore(c) + W_LEX * lex) * 1000) / 1000
  });
}).sort(function (a, b) { return b.rerank_score - a.rerank_score; });

// ---- Relevance gate -----------------------------------------------------
// A chunk that is merely the closest thing in the store is not evidence.
const kept = ranked.filter(function (c) { return c.rerank_score >= q.min_score; });
const context = kept.slice(0, q.top_k).map(function (c, i) { return Object.assign({}, c, { marker: 'C' + (i + 1) }); });

const contextBlock = context.map(function (c) {
  return '[' + c.marker + '] ' + (c.title || c.doc_id || 'untitled') + ' (' + c.doc_id + ')\n' + c.text;
}).join('\n\n');

const sourcesJson = JSON.stringify(context.map(function (c) {
  return { id: c.marker, text: c.text, url: null };
}));

return [{
  json: {
    question: q.question,
    started_at_ms: q.started_at_ms,
    source_workflow: q.source_workflow,
    audience: q.audience,
    has_context: context.length > 0,
    context: context,
    context_block: contextBlock,
    sources_json: sourcesJson,
    diagnostics: {
      retrieved: all.length,
      filtered_out_by_metadata: filteredOut.length,
      filtered_out_detail: filteredOut,
      below_relevance_threshold: ranked.length - kept.length,
      min_score_required: q.min_score,
      score_basis: haveScores ? 'vector_similarity' : 'rank_position_fallback',
      top_rerank_score: ranked.length ? ranked[0].rerank_score : null,
      top_vector_score: ranked.length ? ranked[0].vector_score : null,
      rerank_formula: 'rerank_score = 0.7 * normalised_vector_score + 0.3 * lexical_term_overlap',
      documents_represented: context.map(function (c) { return c.doc_id; }).filter(function (v, i, a) { return a.indexOf(v) === i; })
    }
  }
}];

const r = $('Filter, Rerank and Diagnose').first().json;

function unwrap(n) {
  try { const v = $(n).first().json; return (v && v.json) ? v.json : v; } catch (e) { return null; }
}
const gen = unwrap('Generate Answer (02 Router)');
const verification = unwrap('Verify Answer (09)');
const promptMeta = unwrap('Get RAG Prompt (08)');

const noContext = $input.all().some(function (i) { return i.json && i.json.no_context; });
let answer = (!noContext && gen && gen.ok) ? String(gen.output || '') : null;

// The prompt instructs the model to say INSUFFICIENT_CONTEXT when the passages
// do not answer the question. Honour that literally rather than presenting it
// as an answer.
const declaredInsufficient = !!answer && answer.indexOf('INSUFFICIENT_CONTEXT') !== -1;

// Which retrieved chunks were actually cited, and did the model invent a marker?
const knownMarkers = (r.context || []).map(function (c) { return c.marker; });
const used = [];
const fabricated = [];
if (answer) {
  (answer.match(/\[C\d+\]/g) || []).forEach(function (m) {
    const id = m.slice(1, -1);
    if (knownMarkers.indexOf(id) !== -1) { if (used.indexOf(id) === -1) { used.push(id); } }
    else if (fabricated.indexOf(id) === -1) { fabricated.push(id); }
  });
}

let status = 'answered';
if (noContext) { status = 'no_relevant_context'; }
else if (declaredInsufficient) { status = 'insufficient_context'; }
else if (!answer) { status = 'generation_failed'; }

let confidence = 'none';
if (status === 'answered' && verification) {
  if (verification.verified && verification.score >= 0.85) { confidence = 'high'; }
  else if (verification.score >= 0.7) { confidence = 'medium'; }
  else { confidence = 'low'; }
}

const escalate = status === 'answered' && (!!fabricated.length || (verification && verification.requires_human_review));

return [{
  json: {
    generated_at: new Date().toISOString(),
    n8n_execution_id: $execution.id,
    question: r.question,
    status: status,
    answer: (status === 'answered') ? answer : null,
    confidence: confidence,
    requires_human_review: escalate,
    citations: (r.context || [])
      .filter(function (c) { return used.indexOf(c.marker) !== -1; })
      .map(function (c) { return { marker: c.marker, doc_id: c.doc_id, title: c.title, category: c.category, rerank_score: c.rerank_score, vector_score: c.vector_score, excerpt: String(c.text).slice(0, 220) }; }),
    retrieved_but_uncited: (r.context || [])
      .filter(function (c) { return used.indexOf(c.marker) === -1; })
      .map(function (c) { return { marker: c.marker, doc_id: c.doc_id, rerank_score: c.rerank_score }; }),
    fabricated_markers: fabricated,
    retrieval_diagnostics: r.diagnostics,
    verification: verification ? {
      verified: verification.verified, score: verification.score,
      groundedness: verification.groundedness ? {
        status: verification.groundedness.status,
        claims_judged: verification.groundedness.claims_judged,
        supported: verification.groundedness.supported,
        contradicted: verification.groundedness.contradicted,
        not_stated: verification.groundedness.not_stated
      } : null,
      issues: verification.issues, requires_human_review: verification.requires_human_review
    } : null,
    prompt: promptMeta ? { id: 'rag/answerer', version: promptMeta.version, sha: promptMeta.sha, degraded: promptMeta.degraded } : null,
    model: gen ? { provider: gen.selected_provider, model: gen.selected_model, latency_ms: gen.latency_ms, estimated_cost_usd: gen.estimated_cost_usd } : null,
    estimated_cost_usd: gen ? gen.estimated_cost_usd : 0,
    latency_ms: r.started_at_ms ? (Date.now() - Number(r.started_at_ms)) : null
  }
}];

// Fixtures chosen so that some questions ARE answerable from the corpus and some
// are NOT, and so that metadata access control is tested in BOTH directions.
// Proving a document is blocked is only meaningful if you also prove it would
// otherwise have been returned.
const F = [
  { case_id: 'R01-answerable-policy', question: 'How many days do I have to return an item for a refund?',
    audience: 'public', category_filter: '', top_k: '5', min_score: '0.4',
    expect_status: 'answered', expect_doc: 'POL-001' },
  { case_id: 'R02-not-in-corpus', question: 'What is the chief executive home address and personal phone number?',
    audience: 'public', category_filter: '', top_k: '5', min_score: '0.4',
    expect_status_in: ['no_relevant_context', 'insufficient_context'], expect_doc: null },
  { case_id: 'R03-internal-doc-blocked-from-public', question: 'What time is the Adelaide warehouse despatch cut-off?',
    audience: 'public', category_filter: '', top_k: '5', min_score: '0.4',
    expect_status_in: ['no_relevant_context', 'insufficient_context'], expect_doc: null,
    expect_filtered_doc: 'OPS-210' },
  { case_id: 'R04-same-question-allowed-for-internal', question: 'What time is the Adelaide warehouse despatch cut-off?',
    audience: 'internal', category_filter: '', top_k: '5', min_score: '0.4',
    expect_status: 'answered', expect_doc: 'OPS-210' },
  { case_id: 'R05-category-filter', question: 'What is the hydrostatic head rating of the waterproof membrane?',
    audience: 'public', category_filter: 'product', top_k: '5', min_score: '0.4',
    expect_status: 'answered', expect_doc: 'ENG-101' }
];
return F.map(function (f) { return { json: Object.assign({}, f, { source_workflow: '03-test-suite::' + f.case_id }) }; });

const r = ($json && $json.json) ? $json.json : $json;
const d = r.retrieval_diagnostics || {};
return { json: {
  status: r.status,
  confidence: r.confidence,
  answer: r.answer ? String(r.answer).slice(0, 400) : null,
  cited_docs: (r.citations || []).map(function (c) { return c.doc_id; }),
  fabricated_markers: r.fabricated_markers || [],
  filtered_docs: (d.filtered_out_detail || []).map(function (f) { return f.doc_id; }),
  retrieved: d.retrieved, filtered_out: d.filtered_out_by_metadata,
  below_threshold: d.below_relevance_threshold, score_basis: d.score_basis,
  top_rerank_score: d.top_rerank_score,
  verified: r.verification ? r.verification.verified : null,
  verification_score: r.verification ? r.verification.score : null,
  latency_ms: r.latency_ms, estimated_cost_usd: r.estimated_cost_usd
} };

const fixtures = $('Build RAG Fixtures').all().map(function (i) { return i.json; });
const results = $input.all().map(function (i) { return i.json; });

const rows = results.map(function (r, idx) {
  const fx = fixtures[idx] || {};
  const fails = [];
  const allowed = fx.expect_status_in || (fx.expect_status ? [fx.expect_status] : null);
  if (allowed && allowed.indexOf(r.status) === -1) {
    fails.push('expected status one of [' + allowed.join(', ') + '] but got ' + r.status);
  }
  if (fx.expect_doc && (r.cited_docs || []).indexOf(fx.expect_doc) === -1) {
    fails.push('expected the answer to cite ' + fx.expect_doc + ' but it cited [' + (r.cited_docs || []).join(', ') + ']');
  }
  if (fx.expect_filtered_doc && (r.filtered_docs || []).indexOf(fx.expect_filtered_doc) === -1) {
    fails.push('expected ' + fx.expect_filtered_doc + ' to be filtered out by metadata but it was not');
  }
  if ((r.fabricated_markers || []).length) {
    fails.push('answer invented citation markers: ' + r.fabricated_markers.join(', '));
  }
  return {
    case_id: fx.case_id, pass: fails.length === 0,
    expected_status: allowed ? allowed.join('|') : null, actual_status: r.status,
    expected_doc: fx.expect_doc, cited_docs: r.cited_docs,
    filtered_docs: r.filtered_docs,
    confidence: r.confidence, verified: r.verified, verification_score: r.verification_score,
    retrieved: r.retrieved, filtered_out: r.filtered_out, below_threshold: r.below_threshold,
    score_basis: r.score_basis, top_rerank_score: r.top_rerank_score,
    answer_excerpt: r.answer,
    fail_reasons: fails, latency_ms_measured: r.latency_ms, estimated_cost_usd: r.estimated_cost_usd
  };
});

const passed = rows.filter(function (r) { return r.pass; }).length;
const lats = rows.map(function (r) { return r.latency_ms_measured; }).filter(function (v) { return typeof v === 'number'; }).sort(function (a, b) { return a - b; });
const cost = rows.reduce(function (a, r) { return a + Number(r.estimated_cost_usd || 0); }, 0);

return [{ json: {
  suite: 'rag-fixtures-v1', generated_at: new Date().toISOString(), n8n_execution_id: $execution.id,
  note: 'Run Ingest Corpus first. R03 and R04 ask the SAME question with different audiences, which is what makes the access-control result meaningful rather than an accident of retrieval.',
  total: rows.length, passed: passed, failed: rows.length - passed, all_passed: passed === rows.length,
  latency_ms_p50_measured: lats.length ? lats[Math.max(0, Math.ceil(0.5 * lats.length) - 1)] : null,
  latency_ms_max_measured: lats.length ? lats[lats.length - 1] : null,
  estimated_cost_usd_total: Math.round(cost * 1000000) / 1000000,
  cases: rows
} }];
